// The port's golden sets, generated by the WebAssembly module under Node.
//
//   node crates/kurven-wasm/goldens.mjs <kurven_wasm.wasm> <dir>
//
// Writes each golden file under <dir> at its path, as `kurven-cli fixtures
// <dir>` writes them natively; scripts/check-web.sh then requires the two
// trees to be byte-identical. Node's standard library only: the module
// exports the plain C ABI (crates/kurven-wasm/src/lib.rs), and nothing here
// needs generated glue.

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const [wasmPath, outDir] = process.argv.slice(2);
if (!wasmPath || !outDir) {
  console.error("usage: node goldens.mjs <kurven_wasm.wasm> <dir>");
  process.exit(2);
}

const { instance } = await WebAssembly.instantiate(readFileSync(wasmPath), {});
const wasm = instance.exports;

// The memory can grow while the sets are generated, so read it afresh after.
const count = wasm.goldens();
const bytes = (ptr, len) => new Uint8Array(wasm.memory.buffer, ptr, len);
const utf8 = new TextDecoder("utf-8", { fatal: true });

for (let i = 0; i < count; i++) {
  const path = utf8.decode(bytes(wasm.golden_path_ptr(i), wasm.golden_path_len(i)));
  if (path.startsWith("/") || path.split("/").includes("..")) {
    throw new Error(`golden ${i} has a path outside the set: ${path}`);
  }
  const file = join(outDir, path);
  mkdirSync(dirname(file), { recursive: true });
  // A copy: the view is into the module's memory.
  writeFileSync(file, bytes(wasm.golden_bytes_ptr(i), wasm.golden_bytes_len(i)).slice());
}
console.log(`wrote ${count} golden file(s) from ${wasmPath} under ${outDir}`);
